const app=document.getElementById('app');let answers=[],step=0,busy=false,timer=null,toastTimer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
function focusHeading(){requestAnimationFrame(()=>{const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});});}
function renderHome(){clearTimeout(timer);busy=false;app.innerHTML=`<section class="home"><div class="eyebrow">어느 날, 작고 귀여운 세상에</div><h1>눈 떠보니<br><em>치이카와</em> 세상</h1><p class="intro">풀 뽑기도 하고, 간식도 나눠 먹고.<br>이곳에서 나는 어떤 친구일까요?</p><div class="hero-art">${landscape()}<span class="art-caption">오늘도 잘 부탁해 ♡</span></div><button class="primary start" id="start">나의 작은 하루 시작하기 <span>→</span></button><p class="meta">${questions.length}개의 작은 질문 <b>·</b> 약 3분 <b>·</b> 가입 없이 바로</p><div class="friends"><div class="mini-friends">${Object.keys(characters).map(id=>`<svg viewBox="20 50 160 160" aria-hidden="true"${id==='s'?' style="mix-blend-mode:multiply"':''}>${characterSVG(id)}</svg>`).join('')}</div><span>나와 닮은 ${Object.keys(characters).length}명의 친구들</span></div></section>`;document.getElementById('start').onclick=()=>{answers=[];step=0;renderQuestion();};}
function renderQuestion(){clearTimeout(timer);busy=false;const q=questions[step];app.innerHTML=`<section class="quiz"><div class="quiz-top"><button class="back" id="back">← ${step?'이전 이야기':'처음으로'}</button><span>작은 하루 <strong>${step+1}</strong> / ${questions.length}</span></div><div class="progress" role="progressbar" aria-label="질문 진행" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${step+1}"><div style="width:${(step+1)/questions.length*100}%"></div></div><div class="question-art">${landscape(q.scene)}</div><p class="chapter">CHAPTER ${String(step+1).padStart(2,'0')} · ${q.chapter}</p><h1>${q.title}</h1><p class="question-desc">${q.desc}</p><div class="answers">${q.answers.map((a,i)=>`<button class="answer ${answers[step]===i?'selected':''}" data-answer="${i}" aria-pressed="${answers[step]===i}"><span class="answer-label">${'ABC'[i]}</span><span>${a}</span></button>`).join('')}</div><p class="small-note">정답은 없어요. 마음이 가는 쪽을 골라 주세요.</p></section>`;
 document.getElementById('back').onclick=()=>{if(step){step--;renderQuestion();}else renderHome();};
 app.querySelectorAll('[data-answer]').forEach(btn=>btn.onclick=()=>{if(busy)return;busy=true;answers[step]=Number(btn.dataset.answer);app.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn));});timer=setTimeout(()=>{if(step<questions.length-1){step++;renderQuestion();}else{const result=calculateResult(answers);app.innerHTML=`<section class="loading"><div class="portrait"><svg viewBox="0 0 200 220">${characterSVG('c')}</svg></div><h1>작은 하루를 모아 보는 중…</h1><p>오늘의 당신은 어떤 친구였을까요?</p></section>`;focusHeading();timer=setTimeout(()=>{busy=false;location.hash='result/'+result;},reduced?0:800);}},reduced?0:220);});focusHeading();}
function resultURL(id){return location.origin+location.pathname+'#result/'+id;}
function renderResult(id){const c=characters[id];app.innerHTML=`<section class="result" style="--accent:${c.color}"><div class="result-top"><div class="eyebrow">나의 작은 하루가 알려 준</div><p>나와 닮은 친구를 만났어요!</p></div><div class="result-card"><p class="tiny">MY LITTLE FRIEND</p><h1>${c.name}</h1><div class="portrait"><svg viewBox="0 0 200 220" role="img" aria-label="${c.name} 일러스트"${id==='s'?' style="mix-blend-mode:multiply"':''}>${characterSVG(id)}</svg></div><p class="result-title">${c.title}</p><div class="tags">${c.tags.map(t=>`<span>#${t}</span>`).join('')}</div><p class="result-text">${c.text}</p></div><div class="details">${[['✧','당신의 좋은 점',c.good],['♡','살짝 들킨 당신의 모습',c.secret],['☼','이 세계에서의 하루',c.day]].map(([icon,title,text])=>`<div class="detail"><span class="icon" aria-hidden="true">${icon}</span><div><h2>${title}</h2><p>${text}</p></div></div>`).join('')}</div><div class="actions"><button class="primary" id="save">↓ 결과 카드 저장</button><button class="secondary" id="share">↗ 링크 복사</button></div><div id="fallback"></div><button class="retry" id="retry">↻ 나의 작은 하루 다시 시작하기</button><p class="privacy-note">답변은 서버에 저장되지 않아요.<br>성향 설명은 캐릭터를 바탕으로 한 팬메이드 해석입니다.</p></section>`;
 document.getElementById('retry').onclick=()=>{answers=[];step=0;history.replaceState(null,'',location.pathname+location.search);renderHome();focusHeading();};
 document.getElementById('share').onclick=async()=>{try{await navigator.clipboard.writeText(resultURL(id));toast('결과 링크를 복사했어요!');}catch{const input=document.createElement('input');input.className='copy-fallback';input.readOnly=true;input.value=resultURL(id);input.setAttribute('aria-label','복사할 결과 링크');document.getElementById('fallback').replaceChildren(input);input.focus();input.select();toast('링크를 길게 눌러 복사해 주세요.');}};
 document.getElementById('save').onclick=()=>saveCard(id);focusHeading();}
function wrap(ctx,text,x,y,maxWidth,lineHeight){let line='';for(const ch of text){if(ctx.measureText(line+ch).width>maxWidth){ctx.fillText(line,x,y);line=ch;y+=lineHeight;}else line+=ch;}ctx.fillText(line,x,y);return y;}
async function saveCard(id){const button=document.getElementById('save');button.disabled=true;button.textContent='카드 만드는 중…';try{await document.fonts.ready;const c=characters[id],canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#faf6ec';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#fffdf8';ctx.strokeStyle='#dfd4c4';ctx.lineWidth=3;ctx.beginPath();ctx.roundRect(55,55,970,1240,90);ctx.fill();ctx.stroke();ctx.textAlign='center';ctx.fillStyle='#9b8c76';ctx.font='24px sans-serif';ctx.fillText('눈 떠보니 치이카와 세상',540,135);ctx.fillStyle='#514b43';ctx.font='bold 76px sans-serif';ctx.fillText(c.name,540,245);ctx.fillStyle=c.color;ctx.beginPath();ctx.ellipse(540,535,225,220,0,0,Math.PI*2);ctx.fill();const svg='<svg xmlns="http://www.w3.org/2000/svg" width="400" height="440" viewBox="0 0 200 220">'+characterSVG(id)+'</svg>';const image=new Image();const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});ctx.save();if(id==='s')ctx.globalCompositeOperation='multiply';ctx.drawImage(image,340,300,400,440);ctx.restore();}finally{URL.revokeObjectURL(url);}ctx.fillStyle='#514b43';ctx.font='bold 34px sans-serif';wrap(ctx,c.title,540,825,850,48);ctx.fillStyle='#8e7b65';ctx.font='26px sans-serif';ctx.fillText(c.tags.map(t=>'#'+t).join('   '),540,925);ctx.font='29px sans-serif';wrap(ctx,c.text,540,1010,800,49);ctx.font='21px sans-serif';ctx.fillStyle='#a59885';ctx.fillText('나의 작은 하루 · 비공식 팬메이드 테스트',540,1230);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성 실패');const file=new File([blob],`나의-작은-하루-${c.name}.png`,{type:'image/png'});
 if(/iPhone|iPad/.test(navigator.userAgent)&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'나와 닮은 '+c.name});toast('카드가 준비됐어요.');return;}catch(e){if(e.name==='AbortError')return;}}
 const pngURL=URL.createObjectURL(blob),a=document.createElement('a');a.href=pngURL;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(pngURL),60000);toast('결과 카드를 저장했어요!');
 }catch(e){toast('카드를 저장하지 못했어요. 다시 시도해 주세요.');}finally{button.disabled=false;button.textContent='↓ 결과 카드 저장';}}
function route(){clearTimeout(timer);busy=false;const match=location.hash.match(/^#result\/([chumrks])$/);if(match)renderResult(match[1]);else renderHome();}
window.addEventListener('hashchange',route);document.querySelector('.brand').onclick=e=>{e.preventDefault();history.replaceState(null,'',location.pathname+location.search);renderHome();focusHeading();};route();
